SET NOCOUNT ON; SET XACT_ABORT ON;
DECLARE @P bigint=(SELECT ProjectID FROM dbo.TDADProject WHERE ProjectCode=N'LAOO_DIGITAL_CHECKLIST');
IF @P IS NULL THROW 58004,N'Bootstrap migration must run first.',1;
DECLARE @A TABLE(Code char(5),ActionCode nvarchar(50));
INSERT @A SELECT MenuCode,N'VIEW' FROM dbo.TDADMainMenu WHERE TRY_CONVERT(int,MenuCode) BETWEEN 58001 AND 58010;
INSERT @A VALUES(N'58001',N'EDIT'),(N'58002',N'CREATE'),(N'58002',N'EDIT'),(N'58002',N'DELETE'),(N'58002',N'MANAGE_DEPARTMENT'),(N'58003',N'CREATE'),(N'58003',N'EDIT'),(N'58003',N'DELETE'),(N'58004',N'CREATE'),(N'58004',N'EDIT'),(N'58004',N'DELETE'),(N'58005',N'CREATE'),(N'58005',N'EDIT'),(N'58005',N'DELETE'),(N'58006',N'CREATE'),(N'58006',N'SUBMIT'),(N'58007',N'APPROVE'),(N'58007',N'RETURN'),(N'58008',N'EDIT'),(N'58008',N'HANDOFF'),(N'58009',N'AUDIT'),(N'58009',N'EXPORT'),(N'58010',N'EXPORT');
INSERT dbo.TDADPermission(ProjectID,ScreenCode,ScreenNameTH,ScreenNameEN,ActionCode,ActionNameTH,ActionNameEN,IsActive,CreatedDate) SELECT @P,A.Code,M.MenuName,M.RouteName,A.ActionCode,A.ActionCode,A.ActionCode,1,SYSUTCDATETIME() FROM @A A JOIN dbo.TDADMainMenu M ON M.MenuCode=A.Code;
INSERT dbo.TDADProjectPackage(ProjectID,PackageCode,PackageNameTH,TierCode,BillingCycle,SortOrder,IsActive) VALUES(@P,N'STANDARD',N'มาตรฐาน',N'STANDARD',N'MONTHLY',10,1);
INSERT dbo.TDADProjectPackageFeature(PackageID,FeatureCode,IsEnabled) SELECT P.PackageID,N'DCL_'+M.MenuCode,1 FROM dbo.TDADProjectPackage P CROSS JOIN dbo.TDADMainMenu M WHERE P.ProjectID=@P AND TRY_CONVERT(int,M.MenuCode) BETWEEN 58001 AND 58010;
CREATE TABLE dbo.TDCLSetting(CompanyID bigint NOT NULL PRIMARY KEY,ProjectID bigint NOT NULL,TimeZoneId nvarchar(64) NOT NULL CONSTRAINT DF_TDCLSetting_TZ DEFAULT N'Asia/Bangkok',NotifyInApp bit NOT NULL DEFAULT 1,NotifyEmail bit NOT NULL DEFAULT 0,ReminderMinutes int NOT NULL DEFAULT 60,ServiceMenuCode nvarchar(20) NULL,UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.TDCLGroup(GroupID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,GroupCode nvarchar(30) NOT NULL,GroupName nvarchar(150) NOT NULL,DepartmentOrgUnitID bigint NOT NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDCLGroup UNIQUE(CompanyID,GroupCode));
CREATE TABLE dbo.TDCLType(TypeID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,GroupID bigint NOT NULL,TypeCode nvarchar(30) NOT NULL,TypeName nvarchar(150) NOT NULL,IsActive bit NOT NULL DEFAULT 1,CONSTRAINT UQ_TDCLType UNIQUE(CompanyID,GroupID,TypeCode));
CREATE TABLE dbo.TDCLTemplate(TemplateID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,TypeID bigint NOT NULL,TemplateCode nvarchar(30) NOT NULL,TemplateName nvarchar(150) NOT NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDCLTemplate UNIQUE(CompanyID,TemplateCode));
CREATE TABLE dbo.TDCLTemplateItem(ItemID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,TemplateID bigint NOT NULL,SequenceNo int NOT NULL,ItemText nvarchar(500) NOT NULL,IsRequired bit NOT NULL DEFAULT 1);
CREATE TABLE dbo.TDCLWorkflow(WorkflowID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,TypeID bigint NOT NULL,WorkflowName nvarchar(150) NOT NULL,IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE dbo.TDCLWorkflowStep(StepID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,WorkflowID bigint NOT NULL,SequenceNo int NOT NULL,ApproverUserID bigint NOT NULL);
CREATE TABLE dbo.TDCLSchedule(ScheduleID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,TypeID bigint NOT NULL,TemplateID bigint NOT NULL,WorkflowID bigint NOT NULL,ScheduleName nvarchar(150) NOT NULL,FrequencyCode varchar(10) NOT NULL,TimesJson nvarchar(max) NOT NULL,WeekDaysJson nvarchar(200) NULL,MonthDay int NULL,YearMonth int NULL,ResponsibleEmployeeID bigint NOT NULL,StartsOn date NOT NULL,EndsOn date NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_TDCLSchedule_Frequency CHECK(FrequencyCode IN('DAILY','WEEKLY','MONTHLY','YEARLY')));
CREATE TABLE dbo.TDCLInspection(InspectionID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,ScheduleID bigint NULL,TypeID bigint NOT NULL,DepartmentOrgUnitID bigint NOT NULL,InspectionCode nvarchar(40) NOT NULL,DueAt datetime2 NOT NULL,StartedAt datetime2 NULL,SubmittedAt datetime2 NULL,StatusCode varchar(20) NOT NULL,VersionNo int NOT NULL DEFAULT 1,SnapshotJson nvarchar(max) NULL,CreatedBy bigint NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDCLInspection UNIQUE(CompanyID,InspectionCode),CONSTRAINT UQ_TDCLInspection_Due UNIQUE(CompanyID,ScheduleID,DueAt));
CREATE TABLE dbo.TDCLInspectionVersion(InspectionVersionID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,InspectionID bigint NOT NULL,VersionNo int NOT NULL,SnapshotJson nvarchar(max) NOT NULL,CreatedBy bigint NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDCLInspectionVersion UNIQUE(CompanyID,InspectionID,VersionNo));
CREATE TABLE dbo.TDCLInspectionItem(InspectionItemID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,InspectionID bigint NOT NULL,VersionNo int NOT NULL DEFAULT 1,TemplateItemID bigint NOT NULL,ResultCode varchar(12) NOT NULL,Detail nvarchar(1000) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.TDCLAttachment(AttachmentID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,InspectionID bigint NOT NULL,InspectionItemID bigint NULL,StoragePath nvarchar(500) NOT NULL,ContentType varchar(100) NOT NULL,ByteSize bigint NOT NULL,Sha256 char(64) NOT NULL,CreatedBy bigint NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.TDCLApproval(ApprovalID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,InspectionID bigint NOT NULL,VersionNo int NOT NULL DEFAULT 1,GroupID bigint NOT NULL,StepNo int NOT NULL,ApproverUserID bigint NOT NULL,StatusCode varchar(20) NOT NULL,DecisionNote nvarchar(1000) NULL,DecidedAt datetime2 NULL,CONSTRAINT UQ_TDCLApproval UNIQUE(CompanyID,InspectionID,VersionNo,StepNo));
CREATE TABLE dbo.TDCLCorrectiveTask(TaskID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,InspectionID bigint NOT NULL,InspectionItemID bigint NOT NULL,TaskCode nvarchar(40) NOT NULL,Subject nvarchar(200) NOT NULL,Detail nvarchar(1000) NULL,StatusCode varchar(20) NOT NULL,ServiceHandoffStatus varchar(20) NOT NULL DEFAULT 'PENDING',ServiceTicketID bigint NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ClosedAt datetime2 NULL,CONSTRAINT UQ_TDCLCorrective UNIQUE(CompanyID,InspectionItemID));
CREATE TABLE dbo.TDCLAudit(AuditID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,ActorUserID bigint NOT NULL,ActionCode varchar(30) NOT NULL,EntityCode varchar(30) NOT NULL,EntityID bigint NOT NULL,Detail nvarchar(1000) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.TDCLNotification(NotificationID bigint IDENTITY PRIMARY KEY,CompanyID bigint NOT NULL,UserID bigint NOT NULL,InspectionID bigint NULL,NoticeCode varchar(30) NOT NULL,NoticeKey nvarchar(120) NOT NULL,Message nvarchar(500) NOT NULL,SentAt datetime2 NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_TDCLNotification_Key UNIQUE(CompanyID,UserID,NoticeKey));
CREATE INDEX IX_TDCLInspection_DepartmentDue ON dbo.TDCLInspection(CompanyID,DepartmentOrgUnitID,DueAt,StatusCode);
CREATE INDEX IX_TDCLApproval_Inbox ON dbo.TDCLApproval(CompanyID,ApproverUserID,StatusCode,InspectionID);
CREATE INDEX IX_TDCLSchedule_Active ON dbo.TDCLSchedule(CompanyID,IsActive,StartsOn);
